from typing import List
class Solution:
    def canReach(self, s: str, strs: List[str]) -> List[bool]:
        n = len(s)
        pre = [0] * (n + 1)
        for i, ch in enumerate(s):
            pre[i + 1] = pre[i] + (ch == '1')
        total = pre[n]
        res = []
        for pat in strs:
            F = sum(1 for c in pat if c == '1')
            Q = pat.count('?')
            if not (F <= total <= F + Q):
                res.append(False)
                continue
            b = list(pat)
            need = total - F
            for i in range(n - 1, -1, -1):
                if need == 0:
                    break
                if b[i] == '?':
                    b[i] = '1'
                    need -= 1
            ok = True
            cnt = 0
            for i, c in enumerate(b):
                if c == '?':
                    c = '0'
                cnt += (c == '1')
                if cnt > pre[i + 1]:
                    ok = False
                    break
            res.append(ok)
        return res

