class Solution {
public:
    vector<bool> canReach(string s, vector<string>& strs) {
        int n = s.size();
        vector<int> pre(n + 1, 0);
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + (s[i] == '1');
        int total = pre[n];
        vector<bool> res;
        for (auto& pat : strs) {
            int F = 0, Q = 0;
            for (char c : pat) { F += c == '1'; Q += c == '?'; }
            if (F > total || total > F + Q) { res.push_back(false); continue; }
            string b = pat;
            int need = total - F;
            for (int i = n - 1; i >= 0 && need > 0; i--)
                if (b[i] == '?') { b[i] = '1'; need--; }
            bool ok = true;
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                char c = b[i] == '?' ? '0' : b[i];
                cnt += c == '1';
                if (cnt > pre[i + 1]) { ok = false; break; }
            }
            res.push_back(ok);
        }
        return res;
    }
};

