class Solution {
    public boolean[] canReach(String s, String[] strs) {
        int n = s.length();
        int[] pre = new int[n + 1];
        for (int i = 0; i < n; i++) pre[i + 1] = pre[i] + (s.charAt(i) == '1' ? 1 : 0);
        int total = pre[n];
        boolean[] res = new boolean[strs.length];
        for (int k = 0; k < strs.length; k++) {
            String pat = strs[k];
            int F = 0, Q = 0;
            for (char c : pat.toCharArray()) { if (c == '1') F++; if (c == '?') Q++; }
            if (F > total || total > F + Q) continue;
            char[] b = pat.toCharArray();
            int need = total - F;
            for (int i = n - 1; i >= 0 && need > 0; i--)
                if (b[i] == '?') { b[i] = '1'; need--; }
            boolean ok = true;
            int cnt = 0;
            for (int i = 0; i < n; i++) {
                char c = b[i] == '?' ? '0' : b[i];
                if (c == '1') cnt++;
                if (cnt > pre[i + 1]) { ok = false; break; }
            }
            res[k] = ok;
        }
        return res;
    }
}

